}

class Solution:
    def lengthOfLongestSubstringTwoDistinct(self, s: str) -> int:
        counts={};left=best=0
        for right,ch in enumerate(s):
            counts[ch]=counts.get(ch,0)+1
            while len(counts)>2:
                c=s[left];counts[c]-=1
                if counts[c]==0:del counts[c]
                left+=1
            best=max(best,right-left+1)
        return best

import java.util.*;

class Solution {
    public int lengthOfLongestSubstringTwoDistinct(String s){Map<Character,Integer>cnt=new HashMap<>();int left=0,best=0;for(int right=0;right<s.length();right++){char c=s.charAt(right);cnt.put(c,cnt.getOrDefault(c,0)+1);while(cnt.size()>2){char x=s.charAt(left++);int v=cnt.get(x)-1;if(v==0)cnt.remove(x);else cnt.put(x,v);}best=Math.max(best,right-left+1);}return best;}
}

from typing import Optional

class Solution:
    def getIntersectionNode(self, headA: ListNode, headB: ListNode) -> Optional[ListNode]:
        a,b=headA,headB
        while a is not b:
            a=a.next if a else headB
            b=b.next if b else headA
        return a

class Solution {
    public ListNode getIntersectionNode(ListNode headA,ListNode headB){ListNode a=headA,b=headB;while(a!=b){a=a==null?headB:a.next;b=b==null?headA:b.next;}return a;}
}
